<?php
namespace Modules\BankingMicrofinance\Http\Controllers\Accounting;
use Illuminate\Routing\Controller;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\WriteOff;use Modules\BankingMicrofinance\Entities\WriteOffRecovery;
class WriteOffController extends Controller{public function index(){ $writeOffs=WriteOff::latest()->paginate(25); return view('bankingmicrofinance::accounting.write_offs.index',compact('writeOffs'));} public function create(){return view('bankingmicrofinance::accounting.write_offs.form',['writeOff'=>new WriteOff]);} public function store(Request $r){WriteOff::create($r->all()+['created_by'=>auth()->id(),'status'=>'draft']);return redirect()->route('banking.microfinance.accounting.write-offs.index')->with('status','Write-off drafted.');} public function edit(WriteOff $writeOff){return view('bankingmicrofinance::accounting.write_offs.form',compact('writeOff'));} public function update(Request $r, WriteOff $writeOff){$writeOff->update($r->all());return back()->with('status','Write-off updated.');} public function destroy(WriteOff $writeOff){$writeOff->delete();return back();} public function approve(WriteOff $writeOff){$writeOff->update(['status'=>'approved','approved_by'=>auth()->id(),'approved_at'=>now()]);return back()->with('status','Write-off approved.');} public function recovery(Request $r, WriteOff $writeOff){WriteOffRecovery::create($r->all()+['write_off_id'=>$writeOff->id,'created_by'=>auth()->id()]);return back()->with('status','Recovery recorded.');}}
